func ptrReserveEntry(p unsafe.Pointer, c int32) any {
	r := (*factoringledger.ReserveEntry)(p)
	switch c {
	case 0:
		return (*string)(unsafe.Pointer(&r.ID))
	case 1:
		return (*string)(unsafe.Pointer(&r.OrganizationID))
	case 2:
		return (*string)(unsafe.Pointer(&r.BusinessUnitID))
	case 3:
		return (*string)(unsafe.Pointer(&r.FactoringCompanyID))
	case 4:
		return (*string)(unsafe.Pointer(&r.AgreementID))
	case 5:
		return (*string)(unsafe.Pointer(&r.SubmissionID))
	case 6:
		return (*string)(unsafe.Pointer(&r.SubmissionItemID))
	case 7:
		return (*string)(unsafe.Pointer(&r.InvoiceID))
	case 8:
		return (*string)(unsafe.Pointer(&r.CustomerID))
	case 9:
		return (*string)(unsafe.Pointer(&r.Kind))
	case 10:
		return (*string)(unsafe.Pointer(&r.Treatment))
	case 11:
		return &r.CurrencyCode
	case 12:
		return &r.CashMinor
	case 13:
		return &r.FeeMinor
	case 14:
		return &r.ReserveMinor
	case 15:
		return &r.LiabilityMinor
	case 16:
		return &r.ARMinor
	case 17:
		return (*string)(unsafe.Pointer(&r.JournalEntryID))
	case 18:
		return (*string)(unsafe.Pointer(&r.JournalBatchID))
	case 19:
		return &r.AccountingDate
	case 20:
		return &r.OccurredOn
	case 21:
		return (*string)(unsafe.Pointer(&r.ReversesEntryID))
	case 22:
		return (*string)(unsafe.Pointer(&r.RemittanceLineID))
	case 23:
		return &r.Memo
	case 24:
		return (*string)(unsafe.Pointer(&r.CreatedByID))
	case 25:
		return &r.CreatedAt
	}
	return nil
}

func valueReserveEntry(p unsafe.Pointer, c int32) any {
	r := (*factoringledger.ReserveEntry)(p)
	switch c {
	case 0:
		return string(r.ID)
	case 1:
		return string(r.OrganizationID)
	case 2:
		return string(r.BusinessUnitID)
	case 3:
		return string(r.FactoringCompanyID)
	case 4:
		return string(r.AgreementID)
	case 5:
		return string(r.SubmissionID)
	case 6:
		return string(r.SubmissionItemID)
	case 7:
		return string(r.InvoiceID)
	case 8:
		return string(r.CustomerID)
	case 9:
		return string(r.Kind)
	case 10:
		return string(r.Treatment)
	case 11:
		return r.CurrencyCode
	case 12:
		return r.CashMinor
	case 13:
		return r.FeeMinor
	case 14:
		return r.ReserveMinor
	case 15:
		return r.LiabilityMinor
	case 16:
		return r.ARMinor
	case 17:
		return string(r.JournalEntryID)
	case 18:
		return string(r.JournalBatchID)
	case 19:
		return r.AccountingDate
	case 20:
		return r.OccurredOn
	case 21:
		if r.ReversesEntryID == "" {
			return nil
		}
		return string(r.ReversesEntryID)
	case 22:
		if r.RemittanceLineID == "" {
			return nil
		}
		return string(r.RemittanceLineID)
	case 23:
		if r.Memo == "" {
			return nil
		}
		return r.Memo
	case 24:
		if r.CreatedByID == "" {
			return nil
		}
		return string(r.CreatedByID)
	case 25:
		return r.CreatedAt
	}
	return nil
}

func attachReserveEntry(p unsafe.Pointer, rel int32, child unsafe.Pointer) {
	r := (*factoringledger.ReserveEntry)(p)
	switch rel {
	case 0:
		r.FactoringCompany = (*factoringcompany.FactoringCompany)(child)
	case 1:
		r.Invoice = (*invoice.Invoice)(child)
	case 2:
		r.Customer = (*customer.Customer)(child)
	case 3:
		r.Submission = (*factoringsubmission.Submission)(child)
	}
}

